export default async function main({actions},input) {
 const assigned=await actions.File.handleChooser({selector:'#upload',files:input.files,purpose:'验证隔离页面文件指派'});
 const state=await actions.DOM.getDetails({query:{view:'state',targets:[{selector:'#upload'}]},purpose:'查看文件控件接受结果'});
 return {assigned,details:state.details};
}

export default async function main({actions,context,waitFor},input) {
 const waited=await waitFor({events:['Page.loaded','Page.loadFailed'],pageId:context.pageId,timeoutMs:10000},()=>actions.Page.navigate({url:input.url,purpose:'验证订阅先于导航'}));
 const state=await actions.Page.getState({purpose:'同步导航结果'}); return {event:waited.event.event,title:state.title};
}
